    zh: '一位客人正在使用自助服务。发送任务将结束该操作。',
    ko: '현재 고객이 셀프 서비스를 이용 중입니다. 작업을 보내면 종료됩니다.',
    ar: 'يستخدم أحد النزلاء الخدمة الذاتية الآن. إرسال مهمة يُنهي ذلك.',
    pt: 'Um hóspede está a usar o self-service neste momento. Enviar uma tarefa termina-o.',
    fi: 'Vieras käyttää parhaillaan itsepalvelua. Tehtävän lähettäminen lopettaa sen.',
    is: 'Gestur er að nota sjálfsafgreiðslu núna. Verkefni lýkur henni.',
    sk: 'Hosť práve používa samoobsluhu. Odoslanie úlohy ju ukončí.',
    sl: 'Gost pravkar uporablja samopostrežbo. Pošiljanje naloge jo konča.',
    hu: 'Egy vendég éppen önkiszolgálást használ. Egy feladat elküldése ezt befejezi.',
    ro: 'Un oaspete folosește acum autoservirea. Trimiterea unei sarcini o încheie.',
    bg: 'В момента гост използва самообслужване. Изпращането на задача го прекратява.',
    hr: 'Gost upravo koristi samoposluživanje. Slanje zadatka to prekida.',
    sr: 'Gost upravo koristi samousluživanje. Slanje zadatka ga prekida.',
    mk: 'Гостин моментално користи самопослужување. Испраќањето задача го прекинува.',
    sq: 'Një mysafir po përdor vetëshërbimin tani. Dërgimi i një detyre e përfundon.',
    el: 'Ένας επισκέπτης χρησιμοποιεί αυτή τη στιγμή την αυτοεξυπηρέτηση. Η αποστολή εντολής την τερματίζει.',
