  'kiosk.url.hint': {
    de: 'Bleibt die Seite leer, erlaubt sie keine Anzeige hier. Bitte fragen Sie an der Rezeption.',
    en: 'If the page stays empty, it cannot be shown here. Please ask at the front desk.',
    tr: 'Sayfa boş kalırsa burada gösterilemiyor demektir. Lütfen resepsiyona sorun.',
    nl: 'Blijft de pagina leeg, dan mag ze hier niet worden getoond. Vraag het aan de receptie.',
    da: 'Hvis siden forbliver tom, kan den ikke vises her. Spørg venligst i receptionen.',
    sv: 'Om sidan förblir tom kan den inte visas här. Fråga gärna i receptionen.',
    nb: 'Hvis siden forblir tom, kan den ikke vises her. Spør i resepsjonen.',
    pl: 'Jeśli strona pozostaje pusta, nie może być tutaj wyświetlona. Prosimy zapytać w recepcji.',
    cs: 'Pokud stránka zůstane prázdná, nelze ji zde zobrazit. Zeptejte se prosím na recepci.',
    fr: 'Si la page reste vide, elle ne peut pas être affichée ici. Veuillez vous adresser à la réception.',
    it: 'Se la pagina resta vuota, non può essere mostrata qui. Chieda pure alla reception.',
    es: 'Si la página se queda en blanco, no permite mostrarse aquí. Pregunte en la recepción, por favor.',
    ru: 'Если страница остаётся пустой, её нельзя показать здесь. Пожалуйста, обратитесь на ресепшен.',
    uk: 'Якщо сторінка лишається порожньою, її не можна показати тут. Будь ласка, зверніться до рецепції.',
    zh: '如果页面一直空白，说明该页面不允许在此显示。请咨询前台。',
    ko: '페이지가 비어 있으면 이곳에 표시할 수 없는 페이지입니다. 프런트에 문의해 주세요.',
    ar: 'إذا بقيت الصفحة فارغة، فهي لا تسمح بعرضها هنا. يرجى السؤال في الاستقبال.',
    pt: 'Se a página ficar vazia, não pode ser apresentada aqui. Por favor, pergunte na receção.',
    fi: 'Jos sivu jää tyhjäksi, sitä ei voi näyttää tässä. Kysy vastaanotosta.',
    is: 'Ef síðan helst auð er ekki hægt að sýna hana hér. Vinsamlegast spurðu í móttökunni.',
    sk: 'Ak stránka zostane prázdna, nedá sa tu zobraziť. Opýtajte sa, prosím, na recepcii.',
    sl: 'Če stran ostane prazna, je tukaj ni mogoče prikazati. Prosimo, vprašajte na recepciji.',
    hu: 'Ha az oldal üres marad, itt nem jeleníthető meg. Kérjük, érdeklődjön a recepción.',
    ro: 'Dacă pagina rămâne goală, nu poate fi afișată aici. Vă rugăm să întrebați la recepție.',
    bg: 'Ако страницата остане празна, тя не позволява показване тук. Моля, попитайте на рецепцията.',
    hr: 'Ako stranica ostane prazna, ne dopušta prikaz ovdje. Molimo pitajte na recepciji.',
    sr: 'Ako stranica ostane prazna, ne dozvoljava prikaz ovde. Molimo Vas da pitate na recepciji.',
    mk: 'Ако страницата остане празна, таа не може да се прикаже тука. Ве молиме прашајте на рецепцијата.',
    sq: 'Nëse faqja mbetet bosh, ajo nuk lejon të shfaqet këtu. Ju lutemi pyesni në recepsion.',
    el: 'Αν η σελίδα μείνει κενή, δεν επιτρέπει την προβολή της εδώ. Παρακαλούμε ρωτήστε στη ρεσεψιόν.',
    lt: 'Jei puslapis lieka tuščias, jo čia rodyti negalima. Prašome kreiptis į registratūrą.',
    lv: 'Ja lapa paliek tukša, to šeit nevar parādīt. Lūdzu, jautājiet reģistratūrā.',
    et: 'Kui leht jääb tühjaks, ei luba see end siin kuvada. Palun küsige vastuvõtust.' },

