  'diashow.hint': {
    de: 'Ohne Seiten zeigt das Terminal nur die Begrüßung. Ein Auftrag der Rezeption unterbricht die Diashow.',
    en: 'Without pages the terminal only shows the greeting. A job from the front desk interrupts the slideshow.',
    tr: 'Sayfa olmadan terminal yalnızca karşılama gösterir. Resepsiyondan gelen bir görev slayt gösterisini keser.',
    nl: 'Zonder pagina\'s toont de terminal alleen de begroeting. Een opdracht van de receptie onderbreekt de diavoorstelling.',
    da: 'Uden sider viser terminalen kun velkomsten. En opgave fra receptionen afbryder diasshowet.',
    sv: 'Utan sidor visar terminalen bara hälsningen. Ett uppdrag från receptionen avbryter bildspelet.',
    nb: 'Uten sider viser terminalen bare velkomsthilsenen. Et oppdrag fra resepsjonen avbryter lysbildefremvisningen.',
    pl: 'Bez stron terminal pokazuje tylko powitanie. Zlecenie z recepcji przerywa pokaz slajdów.',
    cs: 'Bez stránek terminál zobrazuje jen uvítání. Úkol z recepce prezentaci přeruší.',
    fr: 'Sans pages, le terminal n’affiche que l’accueil. Une demande de la réception interrompt le diaporama.',
    it: 'Senza pagine il terminale mostra solo il benvenuto. Una richiesta della reception interrompe la presentazione.',
    es: 'Sin páginas, el terminal solo muestra la bienvenida. Una tarea de la recepción interrumpe la presentación.',
    ru: 'Без страниц терминал показывает только приветствие. Задание от ресепшена прерывает слайд-шоу.',
    uk: 'Без сторінок термінал показує лише привітання. Завдання від рецепції перериває слайд-шоу.',
    zh: '没有页面时，终端只显示欢迎语。前台的任务会中断幻灯片。',
    ko: '페이지가 없으면 단말기에는 환영 인사만 표시됩니다. 프런트의 작업이 슬라이드쇼를 중단시킵니다.',
    ar: 'بدون صفحات لا تعرض الشاشة سوى الترحيب. أي مهمة من الاستقبال تقطع عرض الشرائح.',
    pt: 'Sem páginas, o terminal mostra apenas a saudação. Uma tarefa da receção interrompe a apresentação.',
    fi: 'Ilman sivuja pääte näyttää vain tervehdyksen. Vastaanoton tehtävä keskeyttää diaesityksen.',
    is: 'Án síðna sýnir skjárinn aðeins kveðjuna. Verk frá móttökunni truflar myndasýninguna.',
    sk: 'Bez stránok terminál zobrazuje len privítanie. Úloha z recepcie prezentáciu preruší.',
    sl: 'Brez strani terminal prikaže le pozdrav. Naloga recepcije prekine diaprojekcijo.',
    hu: 'Oldalak nélkül a terminál csak az üdvözlést mutatja. A recepció feladata megszakítja a diavetítést.',
    ro: 'Fără pagini, terminalul afișează doar mesajul de bun venit. O sarcină de la recepție întrerupe prezentarea.',
    bg: 'Без страници терминалът показва само поздрава. Задача от рецепцията прекъсва слайдшоуто.',
    hr: 'Bez stranica terminal prikazuje samo pozdrav. Nalog recepcije prekida prezentaciju.',
    sr: 'Bez stranica terminal prikazuje samo pozdrav. Nalog sa recepcije prekida prezentaciju.',
    mk: 'Без страници терминалот го прикажува само поздравот. Налог од рецепцијата го прекинува слајдшоуто.',
    sq: 'Pa faqe, terminali shfaq vetëm përshëndetjen. Një detyrë nga recepsioni e ndërpret diashow-in.',
    el: 'Χωρίς σελίδες το τερματικό δείχνει μόνο τον χαιρετισμό. Μια εργασία από τη ρεσεψιόν διακόπτει την παρουσίαση.',
    lt: 'Be puslapių terminalas rodo tik pasveikinimą. Registratūros užduotis pertraukia skaidrių peržiūrą.',
    lv: 'Bez lapām terminālis rāda tikai sveicienu. Uzdevums no reģistratūras pārtrauc slaidrādi.',
    et: 'Ilma lehtedeta näitab terminal ainult tervitust. Vastuvõtu ülesanne katkestab slaidiseansi.' },
